algorithms.pseudocode:
function MAX_PLUS_INTEGRAL(phi, w):
    best <- -infinity
    for each outcome x:
        v <- phi[x] + w[x]
        if v > best: best <- v
    return best

function RELATIVE_ENTROPY(wq, wp):
    best <- -infinity
    for each outcome x:
        d <- wq[x] - wp[x]
        if d > best: best <- d
    return best

function SCALED_LOG_PARTITION(g, n):
    peak <- max over x of g[x]
    s <- 0
    for each outcome x:
        s <- s + exp( n * (g[x] - peak) )
    return peak + log(s) / n
